"use client";
import { useState } from "react";
import { authClient } from "@/lib/auth-client";
import Turnstile, { TURNSTILE_SITE_KEY } from "@/components/Turnstile";

const ERR: Record<string, string> = {
  INVALID_OTP: "الرمز غير صحيح. تأكد منه وحاول مرة أخرى.",
  OTP_EXPIRED: "انتهت صلاحية الرمز. اطلب رمزاً جديداً.",
  TOO_MANY_ATTEMPTS: "محاولات كثيرة. اطلب رمزاً جديداً.",
  ACCOUNT_LOCKED: "الدخول مقفل مؤقتاً بعد 5 محاولات خاطئة. حاول بعد 15 دقيقة.",
  TURNSTILE_FAILED: "تعذّر التحقق من أنك لست روبوتاً. حدّث الصفحة وحاول مرة أخرى.",
};

export default function LoginForm({ next }: { next: string }) {
  const [step, setStep] = useState<"email" | "otp">("email");
  const [email, setEmail] = useState("");
  const [otp, setOtp] = useState("");
  const [busy, setBusy] = useState(false);
  const [error, setError] = useState("");
  const [captcha, setCaptcha] = useState("");

  async function send(e?: React.FormEvent) {
    e?.preventDefault();
    setError("");
    const clean = email.trim().toLowerCase();
    if (!/^[^\s@]+@[^\s@]+\.[^\s@]{2,}$/.test(clean)) { setError("البريد الإلكتروني غير صحيح."); return; }
    if (TURNSTILE_SITE_KEY && !captcha) { setError("انتظر ثانية حتى يكتمل التحقق من أنك لست روبوتاً، ثم أعد المحاولة."); return; }
    setBusy(true);
    const { error } = await authClient.emailOtp.sendVerificationOtp({ email: clean, type: "sign-in" }, { headers: captcha ? { "x-turnstile-token": captcha } : {} });
    setBusy(false);
    if (error) { setError(error.code === "ACCOUNT_LOCKED" ? ERR.ACCOUNT_LOCKED : error.code === "TURNSTILE_FAILED" ? ERR.TURNSTILE_FAILED : error.status === 429 ? "طلبات كثيرة. انتظر دقائق ثم حاول." : "تعذّر إرسال الرمز الآن. حاول بعد قليل أو تواصل معنا على واتساب."); return; }
    setEmail(clean);
    setStep("otp");
  }

  async function verify(e: React.FormEvent) {
    e.preventDefault();
    setError("");
    if (!/^\d{6}$/.test(otp)) { setError("الرمز 6 أرقام."); return; }
    setBusy(true);
    // أي جلسة سابقة على هذا الجهاز (حساب شخص آخر) تُغلق أولاً، حتى لا يبقى منها شيء بعد الدخول بالحساب الجديد
    await authClient.signOut().catch(() => {});
    const { error } = await authClient.signIn.emailOtp({ email, otp });
    if (error) { setBusy(false); setError(ERR[error.code ?? ""] ?? (error.status === 429 ? "محاولات كثيرة. انتظر دقائق." : "تعذّر الدخول. حاول مرة أخرى.")); return; }
    // تحقق نهائي: الحساب اللي انفتح لازم يكون نفس البريد اللي وصله الرمز، وإلا نغلق الجلسة فوراً
    const { data } = await authClient.getSession({ query: { disableCookieCache: true } });
    if (data?.user?.email?.toLowerCase() !== email.toLowerCase()) {
      await authClient.signOut().catch(() => {});
      setBusy(false);
      setError("تعذّر فتح حسابك بأمان. حدّث الصفحة وادخل مرة ثانية ببريدك.");
      return;
    }
    window.location.assign(next);
  }

  return step === "email" ? (
    <form className="form" onSubmit={send} noValidate>
      <div className="field">
        <label htmlFor="email">البريد الإلكتروني</label>
        <input id="email" type="email" inputMode="email" autoComplete="email" dir="ltr" value={email}
          onChange={(e) => setEmail(e.target.value)} aria-invalid={!!error} aria-describedby="email-hint" required />
        <span id="email-hint" className="hint">نرسل لك رمز دخول من 6 أرقام. بدون كلمة مرور.</span>
      </div>
      <Turnstile action="login" onToken={setCaptcha} />
      {error && <p className="alert err" role="alert">{error}</p>}
      <button className="btn btn-block" disabled={busy}>{busy ? "جارٍ الإرسال…" : "أرسل رمز الدخول"}</button>
    </form>
  ) : (
    <form className="form" onSubmit={verify} noValidate>
      <p>أرسلنا رمزاً إلى <bdi dir="ltr"><b>{email}</b></bdi>. تأكد من مجلد الرسائل غير المرغوبة إذا ما وصل.</p>
      <div className="field">
        <label htmlFor="otp">رمز الدخول</label>
        <input id="otp" type="text" inputMode="numeric" autoComplete="one-time-code" pattern="\d{6}" maxLength={6} dir="ltr"
          value={otp} onChange={(e) => setOtp(e.target.value.replace(/\D/g, ""))} aria-invalid={!!error} required
          style={{ letterSpacing: "0.5em", textAlign: "center", fontSize: 22 }} />
      </div>
      {error && <p className="alert err" role="alert">{error}</p>}
      <button className="btn btn-block" disabled={busy}>{busy ? "جارٍ التحقق…" : "دخول"}</button>
      <div className="row" style={{ justifyContent: "space-between" }}>
        <button type="button" className="link-btn" onClick={() => { setStep("email"); setOtp(""); setError(""); }}>تغيير البريد</button>
        <button type="button" className="link-btn" onClick={() => send()} disabled={busy}>إعادة إرسال الرمز</button>
      </div>
    </form>
  );
}

/** الجهاز داخل بحساب: نعرض صاحبه بوضوح بدل الدخول التلقائي، مع خيار الدخول بحساب آخر */
export function SignedInAs({ name, email, next }: { name: string; email: string; next: string }) {
  const [busy, setBusy] = useState(false);
  return (
    <div className="stack" style={{ ["--space" as string]: "14px" }} data-testid="signed-in-as">
      <p className="alert info">هذا الجهاز داخل بحساب <b>{name}</b> (<bdi dir="ltr">{email}</bdi>).</p>
      <a className="btn btn-block" href={next}>متابعة بهذا الحساب</a>
      <button type="button" className="btn btn-ghost btn-block" disabled={busy}
        onClick={async () => { setBusy(true); await authClient.signOut().catch(() => {}); window.location.reload(); }}>
        {busy ? "جارٍ الخروج…" : "لست أنا: تسجيل الخروج والدخول بحساب آخر"}
      </button>
    </div>
  );
}
